const c = $('Webhook').first().json.body;
const api = (function () {
const DIAS = [0, 1, 2, 3, 4, 5, 6].map((i) => { const f = new Date(c.d + 'T00:00:00Z'); f.setUTCDate(f.getUTCDate() + i); return f.toISOString().slice(0, 10); });
const NOMBRES = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const dias = DIAS.map((fecha) => { const f = new Date(fecha + 'T00:00:00Z'); return { fecha, dia_semana: NOMBRES[f.getUTCDay()], dia_mes: f.getUTCDate() }; });
const porFecha = (lista) => { const m = {}; (lista || []).forEach((x) => { m[x[0]] = x; }); return m; };
const rem = porFecha(c.r);
return {
  desde: c.d,
  hasta: c.h,
  dias,
  remolques_descarga: { etiqueta: c.et, filas_minimas: c.fm, remolques: [], dias: DIAS.map((fecha) => ({ fecha, textos: rem[fecha] ? rem[fecha][1] : [] })) },
  cargadores: c.c.map((x) => { const m = porFecha(x[2]); return { codigo: x[0], b_fila1: x[1], dias: DIAS.map((fecha) => ({ fecha, fila2: m[fecha] ? m[fecha][1] : '', fila3: m[fecha] ? m[fecha][2] : '' })) }; }),
  vehiculos: c.v.map((x) => { const m = porFecha(x[9]); return { bloque: x[0], grupo: x[1] ? { codigo: x[1][0], nombre: x[1][1], abreviatura: x[1][2] } : null, codigo: x[2], matricula: x[3], a: { fila1: x[4], fila2: x[5], fila3: null }, b: { fila1: x[6], fila2: x[7], fila3: x[8] }, dias: DIAS.map((fecha) => ({ fecha, fila2: m[fecha] ? m[fecha][1] : '', fila3: m[fecha] ? m[fecha][2] : 'PENDIENTE CARGA' })) }; }),
};
})();
return [{ json: api }];

const api = $('Expandir').first().json;
const f = new Date(api.desde + 'T00:00:00Z');
const jueves = new Date(f);
jueves.setUTCDate(f.getUTCDate() + 3 - ((f.getUTCDay() + 6) % 7));
const primero = new Date(Date.UTC(jueves.getUTCFullYear(), 0, 4));
const semana = 1 + Math.round(((jueves - primero) / 86400000 - 3 + ((primero.getUTCDay() + 6) % 7)) / 7);
const titulo = String(semana).padStart(2, '0') + '-' + String(jueves.getUTCFullYear()).slice(-2) + 'PRUEBAS';
if (!titulo.endsWith('PRUEBAS')) throw new Error('Solo se escribe en pestañas de pruebas');
return [{ json: { titulo } }];

const api = $('Expandir').first().json;
const hojas = $('Pestañas').first().json;
const v = $('Valores').first().json;
const actual = v && Array.isArray(v.values) ? v : null;
const salida = (function () {
const SUFIJO = 'PRUEBAS';
const COLUMNAS = 10; // A (remolque), B (tractora), C-I (7 días) y J (clave oculta de cada bloque)
const FIJAS = 2;
const COL_CLAVE = 9;

if (!api || !Array.isArray(api.vehiculos) || !Array.isArray(api.dias) || api.dias.length !== 7 || !api.remolques_descarga || !Array.isArray(api.cargadores)) {
  throw new Error('La respuesta de la API no trae el planning completo (vehiculos, cargadores, remolques_descarga y siete dias).');
}

// Semana ISO del lunes (desde) -> nombre de la pestaña, por ejemplo 48-26PRUEBAS.
const f = new Date(api.desde + 'T00:00:00Z');
const jueves = new Date(f);
jueves.setUTCDate(f.getUTCDate() + 3 - ((f.getUTCDay() + 6) % 7));
const primero = new Date(Date.UTC(jueves.getUTCFullYear(), 0, 4));
const semana = 1 + Math.round(((jueves - primero) / 86400000 - 3 + ((primero.getUTCDay() + 6) % 7)) / 7);
const anio2 = String(jueves.getUTCFullYear()).slice(-2);
const titulo = String(semana).padStart(2, '0') + '-' + anio2 + SUFIJO;

// Seguridad: este flujo solo escribe en pestañas de pruebas.
if (!titulo.endsWith(SUFIJO)) throw new Error('Solo se escribe en pestañas acabadas en ' + SUFIJO);

const propiedades = (hojas.sheets || []).map((s) => s.properties);
const existente = propiedades.find((p) => p.title === titulo);
const sheetId = existente ? existente.sheetId : 900000000 + semana * 100 + Number(anio2);
const protegidosActuales = ((hojas.sheets || []).find((s) => s.properties.sheetId === sheetId) || {}).protectedRanges || [];

const COLORES = { cabecera: '00b0f0', remolques: 'fce5cd', cargadores: 'd9d2e9', diania: 'd9ead3', marsaf: 'ead1dc', externo: ['fff2cc', 'c9daf8', 'a2c4c9', 'd9d9d9', 'a4c2f4', 'd0e0e3'], taller: 'ff0000' };
const rgb = (hex) => ({ red: parseInt(hex.slice(0, 2), 16) / 255, green: parseInt(hex.slice(2, 4), 16) / 255, blue: parseInt(hex.slice(4, 6), 16) / 255 });
// Tonalidad más clara de un color: mezcla con blanco (las celdas de texto libre).
const aclarar = (hex) => [0, 2, 4].map((i) => Math.round(parseInt(hex.slice(i, i + 2), 16) + (255 - parseInt(hex.slice(i, i + 2), 16)) * 0.6).toString(16).padStart(2, '0')).join('');
const texto = (v) => (v === null || v === undefined ? '' : String(v));

// Celdas libres (notas de cada día y «Libre» del remolque) que ya había en la pestaña, por clave de bloque.
const previos = {};
if (actual && Array.isArray(actual.values)) {
  actual.values.forEach((fila, i) => {
    const clave = texto(fila[COL_CLAVE]);
    if (!/^[VC]:/.test(clave)) return;
    const dia = (r) => [2, 3, 4, 5, 6, 7, 8].map((c) => texto((actual.values[r] || [])[c]));
    previos[clave] = { notas: dia(i), libreRemolque: texto((actual.values[i + 2] || [])[0]) };
  });
}

const filas = [['REMOLQUE', 'TRACTORA', ...api.dias.map((d) => d.dia_semana.toUpperCase() + ' ' + d.dia_mes), '']];
const bloques = []; // { desde, hasta (índices de fila, hasta excluida), color, borde }
const libres = []; // celdas de texto libre, sin bloquear y en tono claro: { fila, columnaDesde, columnaHasta (excluida), color }
const rojas = []; // celdas con incidencias de taller: { fila, columna }
let conservadas = 0;

const nuevaFila = () => new Array(COLUMNAS).fill('');
const conservar = (clave) => {
  const p = previos[clave];
  if (p && (p.notas.some(Boolean) || p.libreRemolque)) conservadas += 1;
  return p || { notas: new Array(7).fill(''), libreRemolque: '' };
};

// 1) Remolques para descargar: la etiqueta en la columna A y, en cada día, un texto «matrícula // parada» por fila.
{
  const porDia = {};
  (api.remolques_descarga.dias || []).forEach((d) => { porDia[d.fecha] = d.textos || []; });
  const masTextos = Math.max(0, ...api.dias.map((d) => (porDia[d.fecha] || []).length));
  const total = Math.max(api.remolques_descarga.filas_minimas || 0, masTextos);
  const desde = filas.length;
  for (let i = 0; i < total; i++) {
    const fila = nuevaFila();
    if (i === 0) fila[0] = texto(api.remolques_descarga.etiqueta);
    api.dias.forEach((d, j) => { fila[2 + j] = texto((porDia[d.fecha] || [])[i]); });
    filas.push(fila);
  }
  bloques.push({ desde, hasta: filas.length, color: COLORES.remolques, borde: false });
}

// 2) Cargadores: tres filas cada uno.
api.cargadores.forEach((c) => {
  const desde = filas.length;
  const clave = 'C:' + c.codigo;
  const p = conservar(clave);
  const porFecha = {};
  (c.dias || []).forEach((d) => { porFecha[d.fecha] = d; });
  const f1 = nuevaFila(); const f2 = nuevaFila(); const f3 = nuevaFila();
  f1[0] = 'CARGADOR';
  f1[1] = texto(c.b_fila1);
  f1[COL_CLAVE] = clave;
  api.dias.forEach((d, j) => {
    f1[2 + j] = p.notas[j];
    f2[2 + j] = texto((porFecha[d.fecha] || {}).fila2);
    f3[2 + j] = texto((porFecha[d.fecha] || {}).fila3);
  });
  filas.push(f1, f2, f3);
  libres.push({ fila: desde, columnaDesde: 2, columnaHasta: 9, color: aclarar(COLORES.cargadores) });
  bloques.push({ desde, hasta: desde + 3, color: COLORES.cargadores, borde: true });
});

// 3-5) Diania, Marsaf y externos: tres filas cada vehículo.
let grupoAnterior = null;
let indiceGrupo = -1;
api.vehiculos.forEach((v) => {
  const desde = filas.length;
  const clave = 'V:' + v.codigo;
  const p = conservar(clave);
  let color;
  if (v.bloque === 'externo') {
    const grupo = v.grupo ? (v.grupo.codigo || v.grupo.nombre || '') : '';
    if (grupo !== grupoAnterior) { indiceGrupo += 1; grupoAnterior = grupo; }
    color = COLORES.externo[indiceGrupo % COLORES.externo.length];
  } else {
    color = COLORES[v.bloque];
  }
  const porFecha = {};
  (v.dias || []).forEach((d) => { porFecha[d.fecha] = d; });
  const f1 = nuevaFila(); const f2 = nuevaFila(); const f3 = nuevaFila();
  f1[0] = texto(v.a.fila1); f2[0] = texto(v.a.fila2); f3[0] = p.libreRemolque;
  f1[1] = texto(v.b.fila1); f2[1] = texto(v.b.fila2); f3[1] = texto(v.b.fila3);
  f1[COL_CLAVE] = clave;
  api.dias.forEach((d, j) => {
    f1[2 + j] = p.notas[j];
    f2[2 + j] = texto((porFecha[d.fecha] || {}).fila2);
    f3[2 + j] = texto((porFecha[d.fecha] || {}).fila3);
  });
  filas.push(f1, f2, f3);
  libres.push({ fila: desde, columnaDesde: 2, columnaHasta: 9, color: aclarar(color) });
  libres.push({ fila: desde + 2, columnaDesde: 0, columnaHasta: 1, color: aclarar(color) });
  if (f2[0]) rojas.push({ fila: desde + 1, columna: 0 });
  if (f2[1]) rojas.push({ fila: desde + 1, columna: 1 });
  bloques.push({ desde, hasta: desde + 3, color, borde: true });
});

const totalFilas = filas.length;
const filasHoja = Math.max(totalFilas + 20, 100);

// Color esperado de cada celda: el del bloque, más claro en las libres y rojo en las incidencias de taller.
const colores = filas.map((_, i) => {
  if (i === 0) return new Array(COLUMNAS).fill(COLORES.cabecera);
  const b = bloques.find((x) => i >= x.desde && i < x.hasta);
  return new Array(COLUMNAS).fill(b.color);
});
libres.forEach((l) => { for (let j = l.columnaDesde; j < l.columnaHasta; j++) colores[l.fila][j] = l.color; });
rojas.forEach((r) => { colores[r.fila][r.columna] = COLORES.taller; });

const celda = (v) => ({ userEnteredValue: { stringValue: texto(v) } });
const requests = [];
if (!existente) {
  requests.push({ addSheet: { properties: { sheetId, title: titulo, gridProperties: { rowCount: filasHoja, columnCount: COLUMNAS } } } });
} else {
  protegidosActuales.forEach((p) => requests.push({ deleteProtectedRange: { protectedRangeId: p.protectedRangeId } }));
  requests.push({ unmergeCells: { range: { sheetId } } });
  requests.push({ updateCells: { range: { sheetId }, fields: 'userEnteredValue,userEnteredFormat' } });
}
requests.push({ updateSheetProperties: { properties: { sheetId, gridProperties: { rowCount: filasHoja, columnCount: COLUMNAS, frozenRowCount: 1, frozenColumnCount: FIJAS } }, fields: 'gridProperties.rowCount,gridProperties.columnCount,gridProperties.frozenRowCount,gridProperties.frozenColumnCount' } });
requests.push({ updateCells: { start: { sheetId, rowIndex: 0, columnIndex: 0 }, rows: filas.map((fila) => ({ values: fila.map(celda) })), fields: 'userEnteredValue' } });
const todo = { sheetId, startRowIndex: 0, endRowIndex: totalFilas, startColumnIndex: 0, endColumnIndex: COLUMNAS };
requests.push({ repeatCell: { range: { ...todo, startRowIndex: 1 }, cell: { userEnteredFormat: { verticalAlignment: 'TOP', wrapStrategy: 'WRAP' } }, fields: 'userEnteredFormat.verticalAlignment,userEnteredFormat.wrapStrategy' } });
requests.push({ repeatCell: { range: { ...todo, endRowIndex: 1 }, cell: { userEnteredFormat: { backgroundColor: rgb(COLORES.cabecera), horizontalAlignment: 'CENTER', verticalAlignment: 'MIDDLE', textFormat: { bold: true } } }, fields: 'userEnteredFormat.backgroundColor,userEnteredFormat.horizontalAlignment,userEnteredFormat.verticalAlignment,userEnteredFormat.textFormat.bold' } });
bloques.forEach((b) => {
  requests.push({ repeatCell: { range: { sheetId, startRowIndex: b.desde, endRowIndex: b.hasta, startColumnIndex: 0, endColumnIndex: COLUMNAS }, cell: { userEnteredFormat: { backgroundColor: rgb(b.color) } }, fields: 'userEnteredFormat.backgroundColor' } });
  if (b.borde) requests.push({ updateBorders: { range: { sheetId, startRowIndex: b.desde, endRowIndex: b.desde + 1, startColumnIndex: 0, endColumnIndex: COLUMNAS }, top: { style: 'SOLID', color: { red: 0.4, green: 0.4, blue: 0.4 } } } });
});
libres.forEach((l) => requests.push({ repeatCell: { range: { sheetId, startRowIndex: l.fila, endRowIndex: l.fila + 1, startColumnIndex: l.columnaDesde, endColumnIndex: l.columnaHasta }, cell: { userEnteredFormat: { backgroundColor: rgb(l.color) } }, fields: 'userEnteredFormat.backgroundColor' } }));
rojas.forEach((r) => requests.push({ repeatCell: { range: { sheetId, startRowIndex: r.fila, endRowIndex: r.fila + 1, startColumnIndex: r.columna, endColumnIndex: r.columna + 1 }, cell: { userEnteredFormat: { backgroundColor: rgb(COLORES.taller) } }, fields: 'userEnteredFormat.backgroundColor' } }));
[[0, 1, 200], [1, 2, 250], [2, 9, 230]].forEach(([ini, fin, px]) => requests.push({ updateDimensionProperties: { range: { sheetId, dimension: 'COLUMNS', startIndex: ini, endIndex: fin }, properties: { pixelSize: px }, fields: 'pixelSize' } }));
requests.push({ updateDimensionProperties: { range: { sheetId, dimension: 'COLUMNS', startIndex: COL_CLAVE, endIndex: COL_CLAVE + 1 }, properties: { hiddenByUser: true }, fields: 'hiddenByUser' } });
// Toda la pestaña bloqueada salvo las celdas libres (notas de cada día y «Libre» del remolque).
requests.push({ addProtectedRange: { protectedRange: {
  range: { sheetId },
  description: 'Planning de Trans 2000 (n8n): solo se editan las notas de cada día y «Libre»',
  warningOnly: false,
  unprotectedRanges: libres.map((l) => ({ sheetId, startRowIndex: l.fila, endRowIndex: l.fila + 1, startColumnIndex: l.columnaDesde, endColumnIndex: l.columnaHasta })),
} } });

return {
  batch: { requests },
  pestana: { titulo, sheetId, existia: !!existente },
  resumen: {
    semana: api.desde + ' a ' + api.hasta,
    remolques: (api.remolques_descarga.remolques || []).length,
    cargadores: api.cargadores.length,
    vehiculos: api.vehiculos.length,
    filas: totalFilas,
    celdas_libres_conservadas: conservadas,
    rangos_sin_bloquear: libres.length,
    celdas_taller_en_rojo: rojas.length,
    peticiones: requests.length,
  },
  rejilla: filas,
  colores,
  libres: libres.map((l) => ({ fila: l.fila, filas: 1, columnaDesde: l.columnaDesde, columnaHasta: l.columnaHasta })),
};
})();
return [{ json: salida }];

const esp = $('Construir').first().json;
const hoja = $input.first().json.sheets[0];
const filas = hoja.data[0].rowData || [];
const hex = (c) => { if (!c) return 'ffffff'; const f = (v) => Math.round((v ?? 0) * 255).toString(16).padStart(2, '0'); return f(c.red) + f(c.green) + f(c.blue); };
const N = 10;
const leida = esp.rejilla.map((_, i) => Array.from({ length: N }, (__, j) => String(((filas[i] || {}).values || [])[j]?.formattedValue ?? '')));
const ejemplos = [];
let malValores = 0;
let malColores = 0;
const ejemplosColor = [];
esp.rejilla.forEach((fila, i) => {
  for (let j = 0; j < N; j++) {
    const e = String(fila[j] ?? '');
    if (e !== leida[i][j]) { malValores++; if (ejemplos.length < 5) ejemplos.push([i + 1, j + 1, e.slice(0, 40), leida[i][j].slice(0, 40)]); }
    const c = hex(((filas[i] || {}).values || [])[j]?.effectiveFormat?.backgroundColor);
    if (c !== esp.colores[i][j]) { malColores++; if (ejemplosColor.length < 5) ejemplosColor.push([i + 1, j + 1, esp.colores[i][j], c]); }
  }
});
function fnv(s) { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }
const unir = (rs) => rs.map((r) => r.join('\u0001')).join('\n');
const clave = (r) => [r.startRowIndex ?? 0, r.endRowIndex ?? 0, r.startColumnIndex ?? 0, r.endColumnIndex ?? 0].join(',');
const prot = hoja.protectedRanges || [];
const sinBloquearLeidos = (prot[0] ? prot[0].unprotectedRanges || [] : []).map(clave).sort();
const sinBloquearEsperados = esp.libres.map((l) => clave({ startRowIndex: l.fila, endRowIndex: l.fila + l.filas, startColumnIndex: l.columnaDesde, endColumnIndex: l.columnaHasta })).sort();
const grid = hoja.properties.gridProperties;
const rojas = esp.colores.reduce((n, fila) => n + fila.filter((c) => c === 'ff0000').length, 0);
return [{ json: {
  pestana: hoja.properties.title,
  filas: esp.rejilla.length,
  valores_distintos: malValores,
  ejemplos_distintos: ejemplos,
  colores_distintos: malColores,
  ejemplos_color: ejemplosColor,
  celdas_rojas_esperadas: rojas,
  huella: { esperada: fnv(unir(esp.rejilla.map((r) => r.map((c) => String(c ?? ''))))), leida: fnv(unir(leida)) },
  congelado: { filas: grid.frozenRowCount, columnas: grid.frozenColumnCount },
  columna_clave_oculta: !!(hoja.data[0].columnMetadata || [])[9]?.hiddenByUser,
  celdas_unidas: (hoja.merges || []).length,
  proteccion: { rangos: prot.length, aviso_solo: prot[0]?.warningOnly ?? null, sin_bloquear: sinBloquearLeidos.length, esperados: sinBloquearEsperados.length, coinciden: JSON.stringify(sinBloquearLeidos) === JSON.stringify(sinBloquearEsperados) },
} }];
